create table FM_STRUCTURE_PARAM (STRUCTURE_TYPE VARCHAR(3) not null  ,PARAM_TYPE VARCHAR(2) not null  ,LENGTH VARCHAR(50) null  ,START_POS VARCHAR(50) not null  ,END_POS VARCHAR(50) null  ,PADDING_CHAR VARCHAR(10) null  ,SEQ_TYPE VARCHAR(3) null  ,STRING_VALUE VARCHAR(50) null  ,START_INDEX INT null  ,END_INDEX INT null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(STRUCTURE_TYPE,PARAM_TYPE,START_POS));